import{_ as h}from"./plugin-vue_export-helper-c27b6911.js";import{r as a,o as i,c as s,d,a as e,w as o,e as t,f as c}from"./app-36705845.js";const l={},p=d("h1",{id:"指令调度-instruction-scheduling",tabindex:"-1"},[d("a",{class:"header-anchor",href:"#指令调度-instruction-scheduling","aria-hidden":"true"},"#"),t(" 指令调度（Instruction Scheduling）")],-1),u=d("strong",null,"指令调度",-1),_=c(`<h2 id="为什么要调度" tabindex="-1"><a class="header-anchor" href="#为什么要调度" aria-hidden="true">#</a> 为什么要调度</h2><p>现代 CPU 是流水线（甚至超标量）：一条指令从取指到写回要多拍，乘加、访存延迟往往更长。若下一条指令立刻用到上一条的结果，就要<strong>停顿等待</strong>。若中间能插入<strong>互不依赖</strong>的其它指令，流水线就能继续干活。</p><p>调度不能乱改语义：必须尊重数据相关与必要的控制相关，也不能让同一时刻争用的功能部件过载（发射宽度、ALU/AGU/FP 端口等）。因此调度 = 在约束下的<strong>指令重排</strong>。</p><h2 id="主要约束" tabindex="-1"><a class="header-anchor" href="#主要约束" aria-hidden="true">#</a> 主要约束</h2><h3 id="数据相关" tabindex="-1"><a class="header-anchor" href="#数据相关" aria-hidden="true">#</a> 数据相关</h3><p>对寄存器（或内存，分析更保守）上的读写：</p><table><thead><tr><th>名称</th><th>含义</th><th>例子</th></tr></thead><tbody><tr><td>RAW（真相关）</td><td>先写后读</td><td><code>r1 = ...</code> 后 <code>... = r1</code></td></tr><tr><td>WAR（反相关）</td><td>先读后写</td><td>读完 <code>r1</code> 才能改写 <code>r1</code></td></tr><tr><td>WAW（输出相关）</td><td>两次写同一位置</td><td>两次写 <code>r1</code> 的次序要保持结果正确</td></tr></tbody></table><p>真相关决定「结果多久之后才能用」（延迟）；反相关/输出相关在换名（SSA、寄存器分配换名）后有时可减弱，调度器仍常保守处理。</p><h3 id="控制相关与资源" tabindex="-1"><a class="header-anchor" href="#控制相关与资源" aria-hidden="true">#</a> 控制相关与资源</h3><p>分支后面的指令能否上移，取决于是否推测执行、是否在同一基本块内调度。资源方面：每拍能发射几条、哪些功能部件互斥，都会限制「就绪指令」里真正能选出的集合。</p><h2 id="表调度直觉" tabindex="-1"><a class="header-anchor" href="#表调度直觉" aria-hidden="true">#</a> 表调度直觉</h2><p>基本块内调度常用<strong>依赖图 + 列表调度</strong>：</p><ol><li>节点 = 指令；边 = 必须先后（并带延迟）。</li><li>维护<strong>就绪队列</strong>：前驱都已排完、且满足延迟的指令。</li><li>每一拍从就绪队列按启发（关键路径最长、延迟最大、寄存器压力等）选若干条发射，更新后续节点的最早可发射时间。</li></ol><h3 id="小例子" tabindex="-1"><a class="header-anchor" href="#小例子" aria-hidden="true">#</a> 小例子</h3><p>假设 <code>load</code> 结果要 2 拍后才能用，<code>add</code> 延迟 1：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>r1 = load [r0]     // I1，延迟 2
r2 = r3 + r4       // I2，与 load 无关
r5 = r1 + r2       // I3，依赖 I1、I2
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>原序：<code>I1 → I2 → I3</code>。若 <code>I2</code> 紧跟 <code>I1</code>，等 <code>r1</code> 时可能空 1 拍。把 <code>I2</code> 挪到 <code>I1</code> 之后立刻执行，用独立加法填等待，再执行 <code>I3</code>，总时间往往更短。</p>`,17),b=c('<p>就绪顺序可以是：先发 <code>I1</code> 与 <code>I2</code>（若双发射）或 <code>I1</code> 再 <code>I2</code>，最后等延迟满足后发 <code>I3</code>。</p><h2 id="调度与寄存器分配的拉锯" tabindex="-1"><a class="header-anchor" href="#调度与寄存器分配的拉锯" aria-hidden="true">#</a> 调度与寄存器分配的拉锯</h2><p>把无关指令插进长延迟空隙，会<strong>拉长</strong>某些值的活跃区间，寄存器更紧张，可能多 spill；为减少寄存器压力而挤在一起排，又可能<strong>排不满</strong>流水线。编译器常在「表前调度 / 表后调度」间权衡，或在分配后再做一次局部调整。序言里后端三步——选择、调度、分配——在实现上往往<strong>交错、迭代</strong>，而不是严格流水线只走一遍。</p><h2 id="表调度与表后调度" tabindex="-1"><a class="header-anchor" href="#表调度与表后调度" aria-hidden="true">#</a> 表调度与表后调度</h2><table><thead><tr><th></th><th>时机</th><th>特点</th></tr></thead><tbody><tr><td>表调度（pre-RA）</td><td>寄存器分配前</td><td>虚拟寄存器多，自由度大，易拉高寄存器压力</td></tr><tr><td>表后调度（post-RA）</td><td>分配后</td><td>物理寄存器与 spill 已定，重排空间小，适合填剩余空泡、照顾流水线细节</td></tr></tbody></table><p>SelectionDAG 线性化时也有一轮「像调度」的排序；机器级还有 <code>MachineScheduler</code> 一轮。</p><h2 id="小结" tabindex="-1"><a class="header-anchor" href="#小结" aria-hidden="true">#</a> 小结</h2><table><thead><tr><th>要点</th><th>内容</th></tr></thead><tbody><tr><td>目标</td><td>在保持语义下重排，减少等待、提高吞吐</td></tr><tr><td>约束</td><td>数据相关、控制相关、发射/功能部件资源</td></tr><tr><td>方法直觉</td><td>依赖图 + 就绪列表 + 启发选指令</td></tr><tr><td>与 RA</td><td>填空泡 ↔ 活跃区间变长，需要折中</td></tr><tr><td>前后</td><td>输入来自指令选择；输出仍可能含虚拟寄存器，再交给寄存器分配</td></tr></tbody></table>',8);function E(g,m){const r=a("RouterLink"),n=a("Mermaid");return i(),s("div",null,[p,d("p",null,[e(r,{to:"/%E7%BC%96%E8%AF%91%E5%8E%9F%E7%90%86/3.%E5%90%8E%E7%AB%AF/(1)%E6%8C%87%E4%BB%A4%E9%80%89%E6%8B%A9.html"},{default:o(()=>[t("指令选择")]),_:1}),t(" 决定「用哪些机器指令」；"),u,t("决定在依赖与机器资源允许的前提下，「这些指令按什么顺序发射」。目标通常是减少流水线空泡、提高吞吐，有时也兼顾功耗或代码尺寸。选出的指令里往往仍是虚拟寄存器，物理寄存器要交给 "),e(r,{to:"/%E7%BC%96%E8%AF%91%E5%8E%9F%E7%90%86/3.%E5%90%8E%E7%AB%AF/(3)%E5%AF%84%E5%AD%98%E5%99%A8%E5%88%86%E9%85%8D.html"},{default:o(()=>[t("寄存器分配")]),_:1}),t("。")]),_,e(n,{id:"mermaid-116",code:"eJxLy8kvT85ILCpR8AniUlDwNIxW8jRUyMlPTFGKVdDVtat5unvbi/3zFYxqFDyNgXLGCokpQCmQUiMg1wjCBakEynMBAOdjF2E="}),b])}const f=h(l,[["render",E],["__file","(2)指令调度.html.vue"]]);export{f as default};
